UPDATE remediation_contracts
   SET status = 'active', last_verdict = NULL, next_due_at = datetime('now'), verify_transport = 'd1-query',
       precondition = 'ROW-FLIPS-W2E-1 closing probe (W2-E 2026-11-05): replaces the circular birth template; measures that rows 134, 6, 10 and 131 left their waiting states',
       verify_probe = 'SELECT ''1'' AS expected, CASE WHEN (SELECT status FROM roadmap_implementation WHERE id = 134) = ''verified'' AND (SELECT status FROM roadmap_implementation WHERE id = 6) NOT IN (''partial'', ''not-built'', ''open'') AND (SELECT status FROM roadmap_implementation WHERE id = 10) NOT IN (''partial'', ''not-built'', ''open'') AND (SELECT status FROM roadmap_implementation WHERE id = 131) NOT IN (''partial'', ''not-built'', ''open'') THEN ''1'' ELSE ''0'' END AS observed'
 WHERE issue_id = (SELECT id FROM agent_issues WHERE instr(title, 'ROADMAP-1: QNFO.OPS ROW-FLIPS-W2E-1:') = 1 ORDER BY id DESC LIMIT 1)
   AND status IN ('superseded', 'active', 'holding');
